"""Randomised end-to-end validation of the follow-up plan."""
import sys, json, random, itertools
sys.path.insert(0, '/tmp/dev'); sys.path.insert(0, '/workspace/deps'); sys.path.insert(0, '/workspace/submission')
from harness import *
import networkx as nx

def quota_forest(rng, size, prefix):
    nodes = []
    ids = []
    for i in range(size):
        nid = '%s%d' % (prefix, i)
        parent = None if i == 0 or rng.random() < 0.3 else rng.choice(ids)
        nodes.append({'id': nid, 'parent': parent, 'capacity': rng.choice([0, 1, 2, 3, 5, 4096])})
        ids.append(nid)
    # avoid long chains
    for i in range(34, size):
        nodes[i]['parent'] = rng.choice(ids[:min(i, 32)])
    return nodes

def random_campaign(rng):
    nleases = rng.randint(1, 3)
    leases = [lease('L%d' % i, '2001:db8:%x:0000::/56' % i, 0, 200, (0, 1), rng.randint(1, 3))
              for i in range(nleases)]
    services = {}
    for i in range(rng.randint(1, 3)):
        services['s%d' % i] = rng.choice(['tcp', 'adb', 'sync'])
    queries = sorted(rng.sample(range(0, 200), rng.randint(1, 3)))
    rows = []
    n = 0
    manifest = {}
    import ipaddress, hashlib
    for L in leases:
        for sub in L['subnets']:
            base = int(ipaddress.IPv6Network(L['prefix']).network_address) + (sub << 64)
            for k in range(1, L['low_count'] + 1):
                tgt = str(ipaddress.IPv6Address(base + k))
                manifest[(L['id'], tgt)] = '%d/i%d' % (sub, k)
                if rng.random() < 0.8:
                    rows.append(icmp('p%d' % n, 0, 5, 'put', L['id'], 5,
                                     '%d/i%d' % (sub, k), tgt, tgt, 'echo'))
                    n += 1
    for L in leases:
        for sub in L['subnets']:
            base = int(ipaddress.IPv6Network(L['prefix']).network_address) + (sub << 64)
            if rng.random() < 0.2:
                can = hashlib.sha256(('demo\n%s\n%s' % (L['id'], str(ipaddress.IPv6Network((base, 64))))).encode()).digest()
                iid = int.from_bytes(can[:8], 'big') | (1 << 63)
                rows.append(icmp('c%d' % n, 0, 5, 'put', L['id'], 5, '%d/c' % sub,
                                 str(ipaddress.IPv6Address(base + iid)),
                                 str(ipaddress.IPv6Address(base + iid)), 'echo'))
                n += 1
    queries_used = {}
    requests = []
    rids = []
    pool = [tgt for (_, tgt) in manifest]
    for i in range(rng.randint(0, 14)):
        rid = 'r%02d' % i
        at = rng.choice(queries)
        lid = rng.choice(leases)['id']
        tgt = rng.choice(pool + ['2001:db8:ffff::1'])
        requests.append(request(rid, at, lid, tgt, rng.choice(list(services)), rng.choice(['ra0', 'ra1', 'ra2', 'rb0'])))
        rids.append(rid)
    offers = []
    for i in range(rng.randint(0, 12)):
        oid = 'o%02d' % i
        length = rng.choice([32, 48, 56, 64, 80])
        net = ipaddress.IPv6Network((int(ipaddress.IPv6Network('2001:db8::/32').network_address)
                                      + (rng.randrange(0, 1 << 32) << 96), length))
        when = rng.choice([5, 20, 100, 199, 250])
        offers.append(offer(oid, when, rng.choice(list(services)), str(net),
                            rng.choice([0, 1, 2, 3, 8]), rng.choice([0, 1, 3, 17, 1000]),
                            rng.choice(['oa0', 'oa1', 'ob0']),
                            rng.sample(rids, rng.randint(0, len(rids))) if rids else []))
    rq = quota_forest(rng, rng.randint(1, 6), 'ra') + quota_forest(rng, rng.randint(0, 3), 'rb')
    oq = quota_forest(rng, rng.randint(1, 6), 'oa') + quota_forest(rng, rng.randint(0, 3), 'ob')
    seen = set()
    uniq = []
    for node in rq + oq:
        pass
    return campaign(leases, services, queries, [make_capture(rows)] if rows else [],
                    requests=requests, offers=offers, rq=_fix(rq), oq=_fix(oq))

def _fix(nodes):
    ids = [n['id'] for n in nodes]
    out = []
    for n in nodes:
        if n['id'] in ids[:ids.index(n['id'])]:
            continue
        if n['parent'] is not None and n['parent'] not in ids:
            n = dict(n, parent=None)
        out.append(n)
    # break cycles and over-long paths
    changed = True
    guard = 0
    while changed and guard < 50:
        changed = False
        guard += 1
        table = {n['id']: n for n in out}
        for n in out:
            path = []
            at = n['id']
            while at is not None:
                if at in path or len(path) > 32:
                    n['parent'] = None
                    changed = True
                    break
                path.append(at)
                at = table[at]['parent'] if at in table else None
    return out

def brute(job, out):
    """Independently compute the optimum with networkx."""
    active = {row['id']: row['active'] for row in out['active_requests']}
    leases = {l['id']: l for l in job['leases']}
    rnodes = {n['id']: n for n in job['request_quotas']}
    onodes = {n['id']: n for n in job['offer_quotas']}
    requests = {r['id']: r for r in job['requests']}
    edges = []
    for o in job['offers']:
        for rid in o['requests']:
            r = requests[rid]
            if not active.get(rid):
                continue
            if r['service'] != o['service']:
                continue
            if not (r['at'] <= o['time'] < leases[r['lease']]['end']):
                continue
            import ipaddress
            if ipaddress.IPv6Address(r['target']) not in ipaddress.IPv6Network(o['prefix']):
                continue
            edges.append((rid, o['id'], o['cost']))
    G = nx.DiGraph()
    G.add_node('S'); G.add_node('T')
    for rid in {e[0] for e in edges}:
        G.add_edge('S', 'R' + rid, capacity=1, weight=0)
        g = requests[rid]['group']
        prev = 'R' + rid
        seen = set()
        while g is not None and g in rnodes and g not in seen:
            seen.add(g)
            G.add_edge(prev, 'RQ' + g, capacity=rnodes[g]['capacity'], weight=0)
            prev = 'RQ' + g
            g = rnodes[g]['parent']
        if prev != 'R' + rid:
            G.add_edge(prev, 'J', capacity=10 ** 9, weight=0) if 'J' not in G else None
            G.add_edge(prev, 'J', capacity=10 ** 9, weight=0)
    if 'J' in G:
        G.add_edge('J', 'T', capacity=10 ** 9, weight=0)
    for o in job['offers']:
        oid = o['id']
        if not any(e[1] == oid for e in edges):
            continue
        g = o['group']
        prev = 'O' + oid
        G.add_edge(prev, 'OQ' + g, capacity=o['capacity'], weight=0)
        cur = 'OQ' + g
        seen = set()
        while True:
            if cur in seen:
                break
            seen.add(cur)
            p = onodes.get(cur, {}).get('parent') if cur in onodes else None
            if p is None:
                G.add_edge(cur, 'T', capacity=onodes[cur]['capacity'] if cur in onodes else 10 ** 9, weight=0)
                break
            G.add_edge(cur, 'OQ' + p, capacity=onodes[cur]['capacity'], weight=0)
            cur = 'OQ' + p
    for rid, oid, cost in edges:
        G.add_edge('R' + rid, 'O' + oid, capacity=1, weight=cost)
    if not edges:
        return 0, 0
    value = nx.maximum_flow_value(G, 'S', 'T')
    if value == 0:
        return 0, 0
    H = nx.DiGraph(G)
    H.add_node('S', demand=-value); H.add_node('T', demand=value)
    cost, _ = nx.network_simplex(H)
    return value, cost

def feasible(job, out):
    leases = {l['id']: l for l in job['leases']}
    requests = {r['id']: r for r in job['requests']}
    offers = {o['id']: o for o in job['offers']}
    rnodes = {n['id']: n for n in job['request_quotas']}
    onodes = {n['id']: n for n in job['offer_quotas']}
    active = {row['id']: row['active'] for row in out['active_requests']}
    import ipaddress
    rows = out['plan']['assignments']
    ids = [r['request'] for r in rows]
    if ids != sorted(ids):
        return 'not sorted'
    if len(set(ids)) != len(ids):
        return 'duplicate request'
    used = {}
    rq_use = {}
    oq_use = {}
    total = 0
    for row in rows:
        rid, oid = row['request'], row['offer']
        if not active.get(rid):
            return 'inactive request'
        r, o = requests[rid], offers[oid]
        if r['service'] != o['service']:
            return 'service mismatch'
        if not (r['at'] <= o['time'] < leases[r['lease']]['end']):
            return 'time window'
        if ipaddress.IPv6Address(r['target']) not in ipaddress.IPv6Network(o['prefix']):
            return 'prefix'
        if oid not in o['requests']:
            return 'not listed'
        used[oid] = used.get(oid, 0) + 1
        total += o['cost']
        g = r['group']
        while g is not None and g in rnodes:
            rq_use[g] = rq_use.get(g, 0) + 1
            g = rnodes[g]['parent']
        g = o['group']
        while g is not None and g in onodes:
            oq_use[g] = oq_use.get(g, 0) + 1
            g = onodes[g]['parent']
    for oid, count in used.items():
        if count > offers[oid]['capacity']:
            return 'offer capacity'
    for g, count in rq_use.items():
        if count > rnodes[g]['capacity']:
            return 'request quota %s' % g
    for g, count in oq_use.items():
        if count > onodes[g]['capacity']:
            return 'offer quota %s' % g
    if total != out['plan']['cost']:
        return 'cost mismatch %d != %d' % (total, out['plan']['cost'])
    if len(rows) != out['plan']['resolved']:
        return 'resolved mismatch'
    return None

random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
bad = 0
for trial in range(int(sys.argv[2]) if len(sys.argv) > 2 else 60):
    rng = random.Random(trial * 977 + 13)
    job = random_campaign(rng)
    out, errtext = run(job)
    if 'error' in out:
        print('trial', trial, 'ERROR', out, errtext[:300]); bad += 1; continue
    problem = feasible(job, out)
    if problem:
        print('trial', trial, 'INFEASIBLE', problem); bad += 1
    value, cost = brute(job, out)
    if (value, cost) != (out['plan']['resolved'], out['plan']['cost']):
        print('trial', trial, 'OPTIMUM', (value, cost), 'got', (out['plan']['resolved'], out['plan']['cost']))
        bad += 1
print('bad', bad, 'of', trial + 1)
